import{_ as a,o as n,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"ACR 与 SAE 部署链路大白话：镜像拉取与 Secret 权限","description":"","frontmatter":{"title":"ACR 与 SAE 部署链路大白话：镜像拉取与 Secret 权限","date":"2026-06-13T00:00:00.000Z","tags":["阿里云","ACR","SAE","Docker","部署"],"categories":["云开发"]},"headers":[],"relativePath":"posts/云开发/阿里云/ACR 与 SAE 部署链路大白话：镜像拉取与 Secret 权限.md","filePath":"posts/云开发/阿里云/ACR 与 SAE 部署链路大白话：镜像拉取与 Secret 权限.md","lastUpdated":1790163617000}'),t={name:"posts/云开发/阿里云/ACR 与 SAE 部署链路大白话：镜像拉取与 Secret 权限.md"};function i(l,s,c,d,o,r){return n(),e("div",null,[...s[0]||(s[0]=[p(`<p>可以，我给你用“大白话版”讲一下这套关系。</p><p>现在这套部署链路是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的代码</span></span>
<span class="line"><span>  -&gt; 构建成 Docker 镜像</span></span>
<span class="line"><span>  -&gt; 推到 ACR 镜像仓库</span></span>
<span class="line"><span>  -&gt; SAE 从 ACR 拉镜像</span></span>
<span class="line"><span>  -&gt; SAE 启动容器</span></span>
<span class="line"><span>  -&gt; 容器读取 Secret 里的 .env.prod</span></span>
<span class="line"><span>  -&gt; backend 连接 ECS 上的 MySQL / Redis / RabbitMQ / Qdrant / model-api</span></span></code></pre></div><p>核心角色是这几个：</p><p><strong>1. ACR：仓库</strong> ACR 只负责存 Docker 镜像。比如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>crpi-tszoj5zgyyzneya4.cn-shenzhen.personal.cr.aliyuncs.com/herong/maquan:ad7d2960</span></span></code></pre></div><p>它就像“镜像文件的网盘”。<br> 它不运行程序，只保存镜像。</p><p><strong>2. SAE：运行平台</strong> SAE 负责把镜像拉下来，然后运行成容器。<br> 它类似一个托管版 Docker/Kubernetes，你不用自己管服务器进程。</p><p><strong>3. ECS：现在还在放依赖服务</strong> 你的数据库、Redis、RabbitMQ、Qdrant、model-api 目前还在 ECS 上。<br> 所以 SAE 的 backend 启动后，还要访问 ECS 私网 IP：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>192.168.182.143</span></span></code></pre></div><p><strong>4. Secret：密钥柜</strong> 我们有两类 Secret，不是一回事：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>maquan-acr-pull-secret</span></span></code></pre></div><p>这是给 SAE 拉 ACR 镜像用的，相当于“仓库钥匙”。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>maquan-backend-prod-env</span></span></code></pre></div><p>这是给 backend 运行用的，里面是 <code>.env.prod</code>，相当于“应用配置和业务密钥”。</p><p>刚才为什么失败？</p><p>因为控制台能看到镜像，不代表运行时容器也能拉镜像。</p><p>这里有两个身份：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你登录阿里云控制台的主账号</span></span></code></pre></div><p>它可以在页面上看到 ACR 镜像。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SAE 运行时的 Pod / 容器</span></span></code></pre></div><p>它要自己去 ACR 拉镜像。这个运行时没有自动继承你的控制台登录态，所以需要 <code>maquan-acr-pull-secret</code>。</p><p>之前报错：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pull access denied</span></span>
<span class="line"><span>insufficient_scope</span></span>
<span class="line"><span>ImagePullBackOff</span></span></code></pre></div><p>意思就是：SAE 找到了仓库地址，但没有钥匙，仓库拒绝它拉取。</p><p>权限关系可以理解成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>本地电脑 push 镜像到 ACR</span></span>
<span class="line"><span>需要：ACR 用户名 + 固定密码</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ECS 服务器 pull 镜像</span></span>
<span class="line"><span>需要：服务器 docker login 过 ACR</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SAE pull 镜像</span></span>
<span class="line"><span>需要：SAE 里的私有镜像仓库登录 Secret</span></span>
<span class="line"><span></span></span>
<span class="line"><span>backend 连接数据库/Redis</span></span>
<span class="line"><span>需要：.env.prod 里的账号密码 + 网络能通</span></span></code></pre></div><p>所以“能拉镜像”和“能连数据库”是两关：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一关：SAE -&gt; ACR</span></span>
<span class="line"><span>靠 maquan-acr-pull-secret</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第二关：SAE backend -&gt; ECS 私网服务</span></span>
<span class="line"><span>靠 VPC / 安全组 / .env.prod</span></span></code></pre></div><p>现在如果镜像已经能拉下来，说明第一关过了。下一步要看容器日志和健康检查，如果 backend 正常启动并且 <code>/api/v1/health</code> 通过，才说明第二关也基本过了。</p>`,30)])])}const u=a(t,[["render",i]]);export{h as __pageData,u as default};
